#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#define MAX_CHUNK_SIZE 4096
#define HEADER_MAGIC 0xCAFEBABE

typedef struct {
    uint32_t magic;
    int32_t  num_entries;
    int32_t  entry_size;
    uint32_t flags;
} packet_header_t;

typedef struct {
    char *data;
    size_t capacity;
    size_t used;
} secure_buffer_t;

/* Safe format string logging - red herring */
static void log_message(const char *component, const char *fmt, ...) {
    char buf[512];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, sizeof(buf), fmt, args);
    va_end(args);
    fprintf(stderr, "[%s] %s\n", component, buf);
}

static secure_buffer_t *buffer_create(size_t initial_cap) {
    secure_buffer_t *buf = calloc(1, sizeof(secure_buffer_t));
    if (!buf) return NULL;
    buf->data = calloc(1, initial_cap);
    if (!buf->data) { free(buf); return NULL; }
    buf->capacity = initial_cap;
    buf->used = 0;
    return buf;
}

static void buffer_destroy(secure_buffer_t *buf) {
    if (buf) {
        if (buf->data) {
            memset(buf->data, 0, buf->capacity);
            free(buf->data);
        }
        free(buf);
    }
}

/*
 * Computes required allocation size for packet assembly.
 * Each entry needs entry_size bytes plus a 4-byte length prefix.
 * Returns total bytes needed for the payload section.
 */
static int compute_payload_size(int32_t num_entries, int32_t entry_size) {
    /* Validate individual bounds */
    if (num_entries <= 0 || num_entries > 65535) return -1;
    if (entry_size <= 0 || entry_size > 65535) return -1;

    /* Each entry has a 4-byte length prefix + entry_size data */
    int per_entry = entry_size + 4;
    int total = num_entries * per_entry;  /* potential signed overflow */

    /* Sanity check - but this check is defeated by overflow */
    if (total <= 0) return -1;

    return total;
}

/*
 * Validates packet header fields for security.
 * Performs bounds checking on all numeric fields.
 */
static int validate_header(const packet_header_t *hdr) {
    if (hdr->magic != HEADER_MAGIC) {
        log_message("parser", "%s", "invalid magic number");
        return -1;
    }
    if (hdr->num_entries <= 0 || hdr->num_entries > 65535) {
        log_message("parser", "%s", "num_entries out of range");
        return -1;
    }
    if (hdr->entry_size <= 0 || hdr->entry_size > 65535) {
        log_message("parser", "%s", "entry_size out of range");
        return -1;
    }
    if (hdr->flags & 0x80000000) {
        log_message("parser", "%s", "reserved flag set");
        return -1;
    }
    return 0;
}

/*
 * Assembles packet entries into the output buffer.
 * Caller must ensure buf has sufficient capacity.
 */
static int assemble_entries(secure_buffer_t *buf, const uint8_t *input,
                           size_t input_len, int32_t num_entries,
                           int32_t entry_size) {
    size_t offset = 0;
    for (int32_t i = 0; i < num_entries; i++) {
        size_t src_offset = (size_t)i * (size_t)entry_size;
        if (src_offset + entry_size > input_len) {
            log_message("parser", "%s", "input truncated");
            return -1;
        }
        /* Write length prefix */
        uint32_t len = (uint32_t)entry_size;
        memcpy(buf->data + offset, &len, 4);
        offset += 4;
        /* Write entry data */
        memcpy(buf->data + offset, input + src_offset, entry_size);
        offset += entry_size;
    }
    buf->used = offset;
    return 0;
}

/*
 * Main packet processing function.
 * Parses header, validates fields, allocates buffer, assembles output.
 */
int process_packet(const uint8_t *raw_packet, size_t packet_len) {
    if (!raw_packet || packet_len < sizeof(packet_header_t)) {
        log_message("parser", "%s", "packet too short");
        return -1;
    }

    packet_header_t hdr;
    memcpy(&hdr, raw_packet, sizeof(hdr));

    if (validate_header(&hdr) != 0) {
        return -1;
    }

    const uint8_t *payload = raw_packet + sizeof(packet_header_t);
    size_t payload_available = packet_len - sizeof(packet_header_t);

    /* Compute required buffer size using helper */
    int required_size = compute_payload_size(hdr.num_entries, hdr.entry_size);
    if (required_size <= 0) {
        log_message("parser", "%s", "payload size computation failed");
        return -1;
    }

    /* Allocate output buffer - required_size may have overflowed to small positive */
    secure_buffer_t *output = buffer_create((size_t)required_size);
    if (!output) {
        log_message("parser", "%s", "allocation failed");
        return -1;
    }

    log_message("parser", "processing %d entries of size %d (buf=%d)",
                (int)hdr.num_entries, (int)hdr.entry_size, required_size);

    /* Assemble entries into buffer - may write beyond allocated size */
    if (assemble_entries(output, payload, payload_available,
                        hdr.num_entries, hdr.entry_size) != 0) {
        buffer_destroy(output);
        return -1;
    }

    /* Process assembled data (placeholder) */
    log_message("parser", "assembled %zu bytes successfully", output->used);

    buffer_destroy(output);
    return 0;
}

int main(int argc, char **argv) {
    /* Read packet from stdin for testing */
    uint8_t packet[1024*1024];
    size_t n = fread(packet, 1, sizeof(packet), stdin);
    if (n == 0) {
        fprintf(stderr, "No input\n");
        return 1;
    }
    return process_packet(packet, n);
}
